mapper.select:
select *
from rabbit_abnormal_conditions
where house_id = #{houseId}

    and is_deal = #{isDeal}

order by warning_time desc, id desc

select count(1)
from rabbit_abnormal_conditions a
         join rabbits r on r.id = a.rabbit_id and r.house_id = a.house_id
where a.house_id = #{houseId}
  and r.cage_id = #{cageId}
  and a.is_deal = false
